DROP TABLE IF EXISTS `sourcelead`.`ACTION_NAMES`;
CREATE TABLE `sourcelead`.`ACTION_NAMES` (
  `ID` bigint(20) NOT NULL,
  `ACTION_NAME` varchar(100) DEFAULT NULL,
  `METHOD_NAME` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID`)
);

